      fullDescription: 'يتكون مشروع مارينا هيلز العين السخنة (Marina Hills Sokhna) من شاليهات فندقية متطورة تُسلم بتشطيب كامل فندقي ومزودة بنظام البيت الذكي (Smart Home System). يرتبط المشروع بفندق جرافيتي (Gravity Hotel) ليمثل الفرع الخامس لمجموعة فنادق جرافيتي الشهيرة، حيث تتولى الإدارة الفندقية تقديم خدمات التشغيل، الصيانة، والاستقبال، بالإضافة إلى إدارة التأجير وإدارة الاستثمار للوحدات للعملاء الراغبين في استثمار وحداتهم لتحقيق عائد إيجاري دوري. تتميز جميع الوحدات بتصميم معماري فريد يوفر إطلالة مزدوجة (Double View) على مياه البحر الصافية وحمامات السباحة والبحيرات الصناعية، ويضم المشروع شاطئين رمليين خاصين، ومول تجاري يعمل بالفعل، وسينما مفتوحة، ومجمع كلوب هاوس وجيم وسبا فاخر.',
