      fullDescription: 'منتجع بلاتنيوم الغردقة (PLATINUM RESORT) هو مشروع سكني سياحي وفندقي متكامل يمتد على مساحة 11,250 م² في موقع استراتيجي استثنائي بامتداد مجاويش بالغردقة، مباشرة أمام فندق ميركيور وبجوار فندق الباتروس. يتميز المشروع بنسبة بنائية تبلغ حوالي 60% كحد أقصى مع ما يقرب من 19,000 م² من المساحات الترفيهية والمفتوحة أمام المشروع، ومسافات رحبة تبلغ حوالي 32 متراً بين المباني لضمان الخصوصية والإطلالة المريحة. يتكون المنتجع من 5 أدوار تضم حوالي 350 وحدة سكنية متنوعة ما بين استوديوهات (46–56 م²)، ووحدات غرفة نوم واحدة (67–89 م²)، ووحدات غرفتين نوم (100–120 م²)، حيث تم توجيه الأدوار من الأول إلى الثالث لإطلالات مائية على حمامات السباحة، والأدوار الرابع والخامس لإطلالات بحرية بانورامية. يوفر المنتجع حمامين سباحة كبيرين بأبعاد 45 × 10 م، وستريب مول تجاري متكامل للمطاعم والكافيهات والبازارات والبراندات، ومصعدين لكل مبنى، وخدمات فندقية متكاملة تحت إدارة متخصصة ذات خبرة في إدارة الفنادق والمنتجعات السياحية، مع حق استخدام شاطئ فندق 5 نجوم على بُعد حوالي 3 دقائق بالسيارة ومثبت بالعقد، وتشطيب كامل سوبر لوكس، واستلام بنهاية عام 2026.',
