/**
 * Returns a project object localized according to the selected language
 */
export const getLocalizedProject = (project: Project, language: Language): Project => {
  let targetSlug = project.slug;
  if (
    project.slug === 'downtown' ||
    project.slug === 'downtown-1-2' ||
    project.slug === 'downtown-mall' ||
    project.slug === 'downtown-offer'
  ) {
    targetSlug = 'downtown-offices';
  } else if (
    project.slug === 'theisland' ||
    project.slug === 'island-22' ||
    project.slug === 'the-island-marina'
  ) {
    targetSlug = 'the-island';
  } else if (project.slug === 'notion-new-cairo') {
    targetSlug = 'notion';
  } else if (project.slug === 'sokhnatime') {
    targetSlug = 'sokhna-time';
  } else if (project.slug === 'mirai' || project.slug === 'mirai-orbit') {
    targetSlug = 'mirai-complex';
  } else if (project.slug === 'corepoint' || project.slug === 'core_point' || project.slug === 'new-cairo-medical-building') {
    targetSlug = 'core-point';
  } else if (project.slug === 'platinum' || project.slug === 'platinum-resort' || project.slug === 'platinum-hurghada') {
    targetSlug = 'platinum-resort-hurghada';
  } else if (
    project.slug === 'nexus' ||
    project.slug === 'nexus-mall' ||
    project.slug === 'nexus-admin' ||
    project.slug === 'nexus-43' ||
    project.slug === 'nexus-mall-admin-43sqm' ||
    project.slug === 'nuxes' ||
    project.slug === 'nuxes-pharmacy' ||
    project.slug === 'nuxes-mall' ||
    project.slug === 'nuxes-71'
  ) {
    targetSlug = 'nuxes-mall';
  } else if (
    project.slug === 'kernel' ||
    project.slug === 'kernel-mall' ||
    project.slug === 'kernel-business-hub' ||
    project.slug === 'kernel-fnb' ||
    project.slug === 'kernel-mall-fnb' ||
    project.slug === 'kernel-mall-fnb-74sqm' ||
    project.slug === 'kernel-mall-fnb-74sqm-39sqm-outdoor' ||
    project.slug === 'kernal' ||
    project.slug === 'kernal-mall' ||
    project.slug === 'kernal-41' ||
    project.slug === 'kernal-mall-41-sqm-clinic-office-new-cairo'
  ) {
    targetSlug = 'kernal-mall-41-sqm-clinic-office-new-cairo';
  } else if (
    project.slug === 'beit-al-watan-f165' ||
    project.slug === 'beit-al-watan-165' ||
    project.slug === 'f165' ||
    project.slug === 'first-district-beit-al-watan' ||
    project.slug === 'first-district-beit-al-watan-f165' ||
    project.slug === 'beit-al-watan-f165-apartment-196sqm'
  ) {
    targetSlug = 'beit-al-watan-f165-apartment-196sqm';
  }

  const locMap = PROJECT_LOCALIZATIONS[targetSlug];
  if (!locMap || !locMap[language]) {
    return project;
  }

  const loc = locMap[language];

  return {
    ...project,
    name: loc.name || project.name,
    developer: loc.developer || project.developer,
    shortDescription: loc.shortDescription || project.shortDescription,
    fullDescription: loc.fullDescription || project.fullDescription,
    location: loc.location || project.location,
    governorate: (loc.governorate as any) || project.governorate,
    area: loc.area || project.area,
    projectType: (loc.projectType as any) || project.projectType,
    propertyTypes: (loc.propertyTypes as any) || project.propertyTypes,
    amenities: loc.amenities || project.amenities,
    paymentPlans: (loc.paymentPlans as any) || project.paymentPlans,
    startingPrice: loc.startingPrice || project.startingPrice,
    originalPrice: loc.originalPrice || project.originalPrice,
    offerPrice: loc.offerPrice || project.offerPrice,
    cashDiscountPercent: loc.cashDiscountPercent || project.cashDiscountPercent,
    offerDeadline: loc.offerDeadline || project.offerDeadline,
    incentiveScheme: loc.incentiveScheme || project.incentiveScheme,
    isCampaignOffer: loc.isCampaignOffer !== undefined ? loc.isCampaignOffer : project.isCampaignOffer,
    deliveryDate: loc.deliveryDate || project.deliveryDate,
    finishingStatus: loc.finishingStatus || project.finishingStatus,
    availableUnits: loc.availableUnits || project.availableUnits,
    projectStatus: (loc.projectStatus as any) || project.projectStatus,
    badge: loc.badge || project.badge,
    whatsappMessage: loc.whatsappMessage || project.whatsappMessage,
    keyFeatures: loc.keyFeatures || project.keyFeatures,
    doubleViewHighlight: (loc.doubleViewHighlight as any) || project.doubleViewHighlight,
    unitConfigurations: (loc.unitConfigurations as any) || project.unitConfigurations,
    pricingTiers: (loc.pricingTiers as any) || project.pricingTiers,
    hotelOperator: (loc.hotelOperator as any) || project.hotelOperator,
    investmentInfo: (loc.investmentInfo as any) || project.investmentInfo,
    amenityGroups: (loc.amenityGroups as any) || project.amenityGroups,
    videos: (loc.videos as any) || project.videos,
    pricePerMeter: loc.pricePerMeter || project.pricePerMeter,
    launchOffer: (loc.launchOffer as any) || project.launchOffer,
    developmentStatus: (loc.developmentStatus as any) || project.developmentStatus,
    medicalEcosystem: (loc.medicalEcosystem as any) || project.medicalEcosystem,
    availableUnitsList: (loc.availableUnitsList as any) || project.availableUnitsList,
    locationDescription: loc.locationDescription || project.locationDescription,
    locationStatusNote: loc.locationStatusNote || project.locationStatusNote,
    developerPortfolioImage: loc.developerPortfolioImage || project.developerPortfolioImage,
    developerProjectsList: (loc.developerProjectsList as any) || project.developerProjectsList,
    immediateDeliveryBadge: project.immediateDeliveryBadge,
    hideDeliveryDate: loc.hideDeliveryDate !== undefined ? loc.hideDeliveryDate : project.hideDeliveryDate,
    hidePaymentPlans: loc.hidePaymentPlans !== undefined ? loc.hidePaymentPlans : project.hidePaymentPlans,
    nearbyLandmarks: loc.nearbyLandmarks || project.nearbyLandmarks,
    specs: {
      ...project.specs,
      ...(loc.specs || {}),
    },
  };
};
